-- gaps: 3 insert(s), 0 update(s)
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-026', 'RP', 'P1', 'OPEN', NULL, NULL, 'GAP-016 IS NOT CLOSED: REF-01002 FULL TEXT IS UNOBTAINABLE BY EVERY ROUTE AVAILABLE TO THIS ENVIRONMENT, MEASURED ACROSS SEVEN. Batch 17 was convened to read it and could not. Routes, all persisted as artefacts: academia.edu 403 on two different copies, researchgate 403, JSTOR 200 whose body is a bot interstitial, SafetyLit 503 then empty, OpenAlex 429 with the environment budget exhausted. THE INFORMATIVE ONE IS CROSSREF: a bibliographic title search returns five neighbouring papers and not this one, which VERIFIES rather than assumes the no-DOI fact the whole problem rests on -- Journal of Architectural and Planning Research never deposited it. Consensus returned the record and the same abstract, corroborating existence at index level, not full text. WHAT THIS MEANS FOR THE DETERMINATION, UNCHANGED AND SAID AGAIN BECAUSE IT IS THE POINT: extraction 45 stays skim/preliminary, REF-01002 stays UNVERIFIED, gate 1 stays open, C10 keeps refusing the re-determination, parameter 3 x MOB stays undetermined. WHAT WOULD ACTUALLY WORK, and none of it is a search: a library or document-delivery route (JSTOR institutional access, ILL, or a request to the corresponding author, whose consultancy publishes its papers). THAT IS A DIFFERENT KIND OF WORK FROM A RETRIEVAL LADDER and the next batch should plan it as such rather than re-running the same seven routes and recording a second null. AN OPEN METADATA QUESTION RIDES ALONG: TRID prints the fourth author Weiner, Jerome M; a search summary rendered it Welner, J. M. Neither is a retrieved authoritative index. The stored author row says Weiner and is UNCONFIRMED -- settle it with the same retrieval that settles the rest.', '2026-09-18 21:21', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:21', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-027', 'RP', 'P2', 'OPEN', NULL, NULL, 'GAP-018 PREDICTOR PASSED ITS FIRST PROSPECTIVE TEST, 19 AGAINST A PREDICTED FLOOR OF 8 -- AND ONE PASS IS NOT A RESULT. The predictor: a paper cites the literature of its OWN INDEPENDENT VARIABLE, so what an anchor MEASURES predicts its backward yield better than what it is ABOUT. Batch 17 pre-registered a falsifiable floor for REF-00979 (Chow et al., propulsion across a slope series) in two places committed before the pass -- the batch-16 deferral note and this batch priors file -- stating that fewer than 5 matches would WEAKEN the predictor. Measured: 19 of 30. REF-00980 (Sanford 1997) returned 5 of 25 against a prior of 0-2, low on count and exactly right on character. RUNNING TALLY, derive it rather than trusting this line: REF-00985 slope-series biomechanics 23/46, REF-00979 slope-series biomechanics 19/30, REF-00977 effects review 6/117, REF-00980 threshold test 5/25, REF-00984 instrument review 0/38. WHAT IS STILL OWED BEFORE THIS BECOMES DOCTRINE: GAP-018 asked for three or four prospective passes and this is ONE. The two remaining assigned deferrals that can test it are REF-00983 and REF-00986, both slope-adjacent biomechanics, so the predictor says both should yield -- record a floor for each BEFORE the pass. A WEAK INDEPENDENT CORROBORATION arrived unasked: REF-00979 and REF-00985 reference sets OVERLAP on the 1989 portable-ramp paper (10.3109/03790798909166390), which is what the predictor implies two same-variable anchors should do. Weak because two papers in one small literature will overlap anyway; recorded so it is not later mistaken for a second test.', '2026-09-18 21:21', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:21', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-028', 'EG', 'P1', 'OPEN', NULL, NULL, 'THE PRE-1990 RAMP-GRADIENT LITERATURE HAS NO DOIs, AND IT IS WHERE THE 1:12 THRESHOLD PROBABLY COMES FROM. REF-00980 backward pass returned five relevant references, every one pre-1997 and NOT ONE carrying a DOI: a 1957 study to determine the specifications of wheelchair ramps; a 1971 architectural movement study whose Part 3 is titled Ramp gradients; a 1979 accessible-buildings study; a 1981 Dutch paper on accessibility by means of ramps; a 1993 review of technical requirements for ramps written as an RFP attachment. THIS IS A SYSTEMATIC PROPERTY, NOT BAD LUCK, and it now has three independent demonstrations in this corpus: REF-01002 (2009, no DOI, invisible to six batches of DOI-keyed searching), candidates 102 and 103 from batch 16 (no DOI in their deposits), and this entire pre-1990 layer. EVERY SEARCH METHOD THIS PROJECT USES IS DOI-KEYED OR INDEX-KEYED, so the foundation layer of its central parameter is structurally out of reach. WHY IT MATTERS RATHER THAN BEING AN INTERESTING FACT: REF-01002 abstract asserts that design recommendations for running slope and cross slope REST ON LIMITED EMPIRICAL RESEARCH. That is a checkable claim about a NAMED set, and this batch has now named it. If the 1971 Ramp gradients study is the measurement behind 1:12, the codes are anchored; if it is not, they may never have been, and a finding that a code is insufficient is first-class evidence under the 2026-09-13 ruling. EITHER ANSWER IS A RESULT. Closing this needs a library or archive route, the same non-search work GAP-016 now needs, and the two should be planned together.', '2026-09-18 21:21', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:21', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', NULL, NULL, NULL, NULL, NULL);

-- search_executions: 4 insert(s), 0 update(s)
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (71, 'accessible-circulation-geometry', NULL, 'EN', 1, 'co1', 'intrinsic', 'disability rights organisation access audit standard ramp gradient maximum wheelchair user "access audit" DPO published guidance', NULL, 'web', 'scoping', 'none', 9, 9, 0, NULL, NULL, NULL, 0, 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:19', 'ZERO YIELD, AND THE PRIOR CALLED THE SHAPE EXACTLY: every result is a restatement of ADA 1:12 or UK 1:15/1:20 by a commercial ramp vendor, a compliance consultancy or a government body. Not one is a DPO speaking in its own voice. THIS IS THE THIRD CONSECUTIVE Co-1 ZERO on this parameter (HR via HUPT publications index, SV via DHR, now an audit-standard framing in EN), and the pattern is now worth stating as a finding rather than three separate nulls: the Co-1 space for ramp gradient appears genuinely thin, not under-searched. Disabled people organisations on this parameter publish ADVOCACY and BARRIER TESTIMONY, not technical thresholds -- the threshold literature is regulatory or academic. That is a claim about where Co-1 evidence for a NUMERIC parameter lives, and it should be tested against a parameter where lived experience is more directly dispositive before it is generalised.', 0, 'R1 Co-1 pass. Batches 09-12 covered EN/DE/FR/NL/ES/JA; batch 16 added HR and SV, both well-formed zero yields. Expect another generic pass to re-find nothing. The untried angle with real prospect is a DPO that publishes an access-AUDIT STANDARD rather than advocacy -- expect low yield, and expect any hit to be T5/T6 regulatory restatement rather than Co-1, which is what the SV pass found.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (72, 'accessible-circulation-geometry', NULL, 'EN', 1, 'clinical', 'high_control', 'R10 full-text retrieval ladder for REF-01002 (Vredenburgh et al. 2009, JAPR 26(2):145-158, no DOI): academia.edu x2, researchgate, jstor.org/stable/43030866, safetylit JAPR 26(2) index, api.openalex.org title search, api.crossref.org bibliographic search', NULL, 'web', 'systematic', 'none', 7, 7, 0, NULL, NULL, NULL, 0, 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:19', 'THE PRIOR HELD AND GAP-016 IS NOT CLOSED. Seven routes, every one persisted as an artefact because a failed retrieval is retrieved evidence of a failed retrieval: academia.edu 403 (two different copies), researchgate 403, JSTOR 200 but the body is a bot interstitial not the article, SafetyLit 503 then an empty body, OpenAlex 429 (budget exhausted for this environment, resets midnight UTC). CROSSREF IS THE ONE INFORMATIVE NULL: a bibliographic title search returns five neighbouring papers and NOT this one, which VERIFIES rather than assumes the no-DOI fact the whole GAP-016 problem rests on -- JAPR never deposited it. CONSENSUS returned the record with the same abstract and the byline Alison G. Vredenburgh et al., corroborating existence and authorship-lead at index level, still not full text. CONSEQUENCE, STATED PLAINLY: extraction 45 stays skim/preliminary, REF-01002 stays UNVERIFIED, determination gate 1 stays open, C10 keeps refusing the re-determination, and parameter 3 x MOB stays undetermined. Nothing about the 7 percent figure moved and nothing should have. AN UNRESOLVED METADATA DISCREPANCY IS ALSO RECORDED: TRID prints the fourth author as Weiner, Jerome M; a web-search summary rendered it Welner, J. M. Neither is a retrieved authoritative index and this batch could not settle it -- the stored author row says Weiner and is flagged as unconfirmed.', 0, 'JAPR is a small independent journal (Locke Science) with no DOI registration and no open archive I expect to resolve. Routes in order: JSTOR, university repository, ResearchGate/Academia, author pages. I expect retrieval to be the hard part of this batch and I put it BELOW EVEN ODDS. If it fails that is a recorded null and the figure stays where it is; it is not licence to promote the extraction.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (73, 'accessible-circulation-geometry', NULL, 'EN', 1, 'clinical', 'high_control', 'https://api.crossref.org/works/10.1016/j.apmr.2008.07.019 -- deposited reference list of REF-00979, screened for ramp/slope/gradient relevance (GAP-025 item 2)', NULL, 'crossref', 'systematic', 'backward', 30, 30, 0, NULL, NULL, NULL, 0, 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:19', 'PREDICTION MET, AND THIS IS THE PREDICTOR FIRST PROSPECTIVE TEST RATHER THAN A THIRD RETROSPECTIVE OBSERVATION. Predicted >= 8 of the references would match; 19 OF 30 DO. The prediction was written into the deferral note in batch 16 and into this batch priors file, both committed before the pass ran, so it is a test and not a description. GAP-018 asked for three or four such passes before the predictor is treated as doctrine; this is one, and it should be counted as one rather than as confirmation. WHAT THE SEAM CONTAINS: the propulsion-on-slopes literature almost in full -- kinetic analysis on indoor and outdoor surfaces, uphill handrim biomechanics, load on the upper extremity, EMG during paraplegic propulsion, and TWO 1989 portable-ramp papers (10.1177/030802268905201209 and 10.3109/03790798909166390, the latter already staged as candidate 101 in batch 16, which is a cross-confirmation that the two anchors reference sets overlap where the predictor says they should). DEPTH-1: nothing discovered here is mined in this pass.', 0, 'A PRE-REGISTERED TEST OF GAP-018. Under the predictor -- a paper cites the literature of its own independent variable -- Chow et al. measure propulsion across a slope series, so they should cite the propulsion-on-slopes literature. QUANTIFIED SO IT CAN FAIL: I predict >= 8 of its references match the ramp/slope/gradient screen. Batch 16 observed 23/46 for a slope-series biomechanics paper against 0/38 for an instrument review. IF CHOW RETURNS < 5 THE PREDICTOR IS WEAKENED and GAP-018 must record that rather than quietly dropping it.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (74, 'accessible-circulation-geometry', NULL, 'EN', 1, 'clinical', 'high_control', 'https://api.crossref.org/works/10.1080/10400435.1997.10132293 -- deposited reference list of REF-00980, screened for ramp/slope/gradient relevance (GAP-025 item 3)', NULL, 'crossref', 'systematic', 'backward', 25, 25, 0, NULL, NULL, NULL, 0, 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:19', 'PRIOR SLIGHTLY LOW ON COUNT (5 of 25, predicted 0-2) AND EXACTLY RIGHT ON CHARACTER, WHICH IS THE MORE USEFUL HALF. Every one of the five is pre-1997 and NOT ONE CARRIES A DOI: a 1957 study to determine the specifications of wheelchair ramps; a 1971 architectural movement study whose Part 3 is titled Ramp gradients; a 1979 accessible-buildings study; a 1981 Dutch research paper on accessibility by means of ramps; and a 1993 review of technical requirements for ramps prepared as an attachment to a request for proposals. THIS IS THE FOUNDATION LAYER OF THE WHOLE 1:12 LINEAGE and it is invisible to every DOI-keyed pass this project can run -- the same blind spot that hid REF-01002 for six batches, now showing up as a systematic property of the pre-1990 accessibility literature rather than as one unlucky paper. It also means REF-01002 abstract claim that design recommendations rest on limited empirical research is CHECKABLE against a named set rather than taken on trust. DEPTH-1: nothing discovered here is mined in this pass.', 0, 'Sanford 1997. LOW YIELD EXPECTED, 0-2 relevant. A 1997 paper cites pre-1997 work, and the pre-1997 ramp-slope empirical literature is exactly what REF-01002 abstract calls limited. Run because GAP-025 assigns it and because a null on a named anchor is a completed unit of work.');

-- search_candidates: 7 insert(s), 0 update(s)
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (107, 71, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Impact of Running Slope and Cross Slope on the Difficulty Level of Outdoor Pathways (Longmuir, Environment and Behavior, 2003)', 'surfaced via Consensus; DOI not yet resolved', 'UNVERIFIED', 1, 0, 'HYPOTHESIS, AND THE HIGHEST-VALUE LEAD OF THIS BATCH. A SECOND independent perceived-difficulty study on running slope AND cross slope -- 23 participants with vision or mobility limitations rating path difficulty against PROPOSED accessibility guidelines. That is GAP-002 acceptability question directly, from a different laboratory and six years before REF-01002. Its reported finding that slopes exceeding the guidelines may also be acceptable FOR VERY SHORT DISTANCES or on hard/paved surfaces is DISTANCE-CONDITIONED in the same way REF-01002 7 percent is conditioned on 20 ft and REF-00996 states as its mechanism -- three sources, three methods, one conditioning structure. NOT ADMITTED: reached through a Consensus record, not a retrieved payload; needs the R10 ladder and a tier call. Note the population is mixed vision AND mobility, so the match grade will not be EXACT.', NULL, 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:20');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (108, 71, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Effects of Ramp Slope and Height on Usability and Physiology during Wheelchair Driving (Kim et al., HFES Proceedings, 2010)', 'surfaced via Consensus; DOI not yet resolved', 'UNVERIFIED', 1, 0, 'HYPOTHESIS. Five slope levels (1:6, 1:8, 1:10, 1:12, 1:14) crossed with THREE RISE HEIGHTS (15, 30, 45 cm) -- the rise-conditioned design this parameter needs and has never had in the corpus, plus perceived discomfort alongside EMG and pulse. Its reported conclusions bear directly on two live questions: no significant difference between 1:10 and 1:12, and slope effects minor at low rise. RELATED TO BUT NOT THE SAME AS candidate 88 (Kim 2014), which GAP-008 blocked -- this is the 2010 HFES paper, and the pair should be resolved together. Not admitted: Consensus record, not a retrieved payload.', NULL, 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:20');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (109, 74, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Four architectural movement studies for the wheelchair and ambulant disabled. Part 3 - Ramp gradients (1971)', 'no DOI; entry 24 of 25 in REF-00980 Crossref deposit', 'UNVERIFIED', 3, 0, 'HYPOTHESIS, AND POSSIBLY THE ROOT OF THE 1:12 LINEAGE. A 1971 architectural movement study whose Part 3 is titled Ramp gradients, cited by the 1997 study that tested the ADA-permitted range. If the modern codes trace to a measurement study, this is a strong candidate for where. NO DOI, so unreachable by every DOI-keyed method this project runs -- resolution needs a library or archive route, which is a different kind of work from a Crossref chase and should be planned as such rather than attempted opportunistically.', NULL, 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:20');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (110, 74, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'A study to determine the specifications of wheelchair ramps (1957)', 'no DOI; entry 9 of 25 in REF-00980 Crossref deposit', 'UNVERIFIED', 3, 0, 'HYPOTHESIS. The oldest ramp-specification study in any reference list this corpus holds. Same locator problem as the 1971 study and the same reason to want it: a specification study from 1957 is either the origin of a threshold still in force or evidence that the threshold was never measured at all, and both answers matter to GAP-002.', NULL, 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:20');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (111, 74, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Accessibility by means of ramps - Some research data from the Netherlands (1981)', 'no DOI; entry 22 of 25 in REF-00980 Crossref deposit', 'UNVERIFIED', 3, 0, 'HYPOTHESIS. Non-English-origin empirical ramp research, and R5 applies: non-indexation is an INDEXING fact, not an evidence-quality fact. The corpus already holds REF-00996, a Flemish handbook stating the rise-conditioning mechanism; a 1981 Dutch research paper may be part of the same lineage and would be a second non-anglophone empirical input on this parameter.', NULL, 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:20');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (112, 73, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'A kinetic analysis of manual wheelchair propulsion during start-up on select indoor and outdoor surfaces (JRRD, 2005)', '10.1682/JRRD.2004.08.0106', 'UNVERIFIED', 1, 0, 'HYPOTHESIS. JRRD, therefore open access and cheaply retrievable. Start-up kinetics across surfaces rather than a slope series, so it likely bears on surface rather than gradient -- staged for completeness of the M2 seam and ranked below the slope-series papers.', NULL, 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:20');
